import { MODULES, type ModuleId } from '@ecb/shared';

/**
 * The entry page each module shows until its owner builds the real one.
 * Module owners replace the route that renders it; they do not edit this file.
 */
export function ModuleLanding({ moduleId }: { moduleId: ModuleId }) {
  const module = MODULES[moduleId];

  return (
    <section className="rounded-2xl border border-coffee-200 bg-white p-8">
      <p className="text-sm font-semibold tracking-wide text-coffee-500 uppercase">
        Module {module.number}
      </p>
      <h1 className="mt-1 text-2xl font-bold">{module.name}</h1>
      <p className="mt-3 max-w-2xl text-coffee-700">{module.summary}</p>
      <p className="mt-6 text-sm text-coffee-700">
        This module is not built yet. Its code lives in{' '}
        <code className="rounded bg-coffee-100 px-1.5 py-0.5">
          apps/web/src/modules/{module.id}
        </code>{' '}
        and{' '}
        <code className="rounded bg-coffee-100 px-1.5 py-0.5">
          apps/api/src/modules/{module.id}
        </code>
        .
      </p>
    </section>
  );
}
